        Set<LocalDate> holidays = new HashSet<>(jdbc.query("SELECT holiday_date FROM " + AsOf.table("holiday")
                + " WHERE sheet_id = ? AND holiday_date >= ?", (rs, n) -> rs.getObject(1, LocalDate.class), sheetId,
                Date.valueOf(date)));
        LocalDate due = date;
        while (holidays.contains(due)) {
            due = due.plusDays(1);
        }
        return due;
    }
}
